// ============================================================================
// FILE: firefox-performance-tuner/src/components/VideoPlayer.jsx
// PURPOSE: Front-end component for YouTube video playback with progress bar
// ============================================================================

import { useState, useEffect } from "react";

/**
 * VIDEO PLAYER COMPONENT WITH PROGRESSIVE DOWNLOAD
 * 
 * Features:
 *  - Input field for YouTube URL
 *  - Player selection (MPV/VLC)
 *  - Real-time progress bar
 *  - Cancel button
 *  - Status messages
 * 
 * UX Flow:
 *  1. User enters YouTube URL and clicks "Play"
 *  2. API starts download, returns download ID
 *  3. Component polls /api/download-progress/:id every 1 second
 *  4. Progress bar updates in real-time
 *  5. Status changes: "Starting..." → "Downloading..." → "Playing..." → "Complete"
 *  6. User can cancel at any time
 */
export default function VideoPlayer() {

  // STATE MANAGEMENT
  const [url, setUrl] = useState("");
  const [player, setPlayer] = useState("mpv");
  const [downloadId, setDownloadId] = useState(null);
  const [progress, setProgress] = useState(0);
  const [status, setStatus] = useState("idle"); // idle | downloading | playing | complete | error
  const [errorMessage, setErrorMessage] = useState("");

  /**
   * START DOWNLOAD
   * 
   * Calls: POST /api/play-in-external-player
   * Response: { success, id, file, player, message, resumable, progressive }
   * 
   * On success:
   *  - Store download ID
   *  - Set status to "downloading"
   *  - Start progress polling (useEffect below)
   */
  const handlePlay = async () => {

    // Validate URL
    if (!url || !url.match(/^https?:\/\/.+/i)) {
      setErrorMessage("Please enter a valid URL");
      return;
    }

    setStatus("downloading");
    setProgress(0);
    setErrorMessage("");

    try {

      const response = await fetch("/api/play-in-external-player", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url, player })
      });

      const data = await response.json();

      if (!data.success) {
        setStatus("error");
        setErrorMessage(data.error || "Download failed");
        return;
      }

      // Store download ID to start polling
      setDownloadId(data.id);

    } catch (error) {
      setStatus("error");
      setErrorMessage(error.message);
    }
  };

  /**
   * CANCEL DOWNLOAD
   * 
   * Calls: POST /api/cancel-download
   * Body: { id: downloadId }
   * 
   * On success:
   *  - Stop polling (clear downloadId)
   *  - Reset status to idle
   */
  const handleCancel = async () => {

    if (!downloadId) return;

    try {

      await fetch("/api/cancel-download", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: downloadId })
      });

      // Reset state
      setDownloadId(null);
      setProgress(0);
      setStatus("idle");

    } catch (error) {
      console.error("Cancel failed:", error);
    }
  };

  /**
   * PROGRESS POLLING
   * 
   * Runs when downloadId is set
   * Polls /api/download-progress/:id every 1 second
   * Updates progress bar and status
   * 
   * Status transitions:
   *  - downloading: progress < 100, playerPid === null
   *  - playing: playerPid !== null
   *  - complete: progress === 100 or done === true
   */
  useEffect(() => {

    // Only poll if download is active
    if (!downloadId) return;

    const interval = setInterval(async () => {

      try {

        const response = await fetch(`/api/download-progress/${downloadId}`);
        const data = await response.json();

        // Update progress
        setProgress(data.progress || 0);

        // Check if download is complete
        if (data.done || data.progress >= 100) {
          setStatus("complete");
          setDownloadId(null); // Stop polling
          return;
        }

        // Check if player has launched
        if (data.playerPid) {
          setStatus("playing");
        }

      } catch (error) {
        console.error("Progress poll failed:", error);
      }

    }, 1000); // Poll every 1 second

    // Cleanup: stop polling when component unmounts or downloadId changes
    return () => clearInterval(interval);

  }, [downloadId]);

  /**
   * RENDER UI
   */
  return (
    <div style={{ padding: "20px", maxWidth: "600px" }}>

      <h2>🎬 YouTube Video Player</h2>

      {/* URL INPUT */}
      <div style={{ marginBottom: "10px" }}>
        <input
          type="text"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          placeholder="Enter YouTube URL"
          style={{
            width: "100%",
            padding: "10px",
            fontSize: "16px",
            border: "1px solid #ccc",
            borderRadius: "4px"
          }}
          disabled={status === "downloading" || status === "playing"}
        />
      </div>

      {/* PLAYER SELECTION */}
      <div style={{ marginBottom: "10px" }}>
        <label style={{ marginRight: "20px" }}>
          <input
            type="radio"
            value="mpv"
            checked={player === "mpv"}
            onChange={(e) => setPlayer(e.target.value)}
            disabled={status === "downloading" || status === "playing"}
          />
          {" "}MPV
        </label>
        <label>
          <input
            type="radio"
            value="vlc"
            checked={player === "vlc"}
            onChange={(e) => setPlayer(e.target.value)}
            disabled={status === "downloading" || status === "playing"}
          />
          {" "}VLC
        </label>
      </div>

      {/* ACTION BUTTONS */}
      <div style={{ marginBottom: "20px" }}>
        {status === "idle" || status === "complete" || status === "error" ? (
          <button
            onClick={handlePlay}
            style={{
              padding: "10px 20px",
              fontSize: "16px",
              background: "#4CAF50",
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer"
            }}
          >
            ▶ Play
          </button>
        ) : (
          <button
            onClick={handleCancel}
            style={{
              padding: "10px 20px",
              fontSize: "16px",
              background: "#f44336",
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer"
            }}
          >
            ✖ Cancel
          </button>
        )}
      </div>

      {/* PROGRESS BAR */}
      {(status === "downloading" || status === "playing") && (
        <div style={{ marginBottom: "10px" }}>
          <div style={{
            width: "100%",
            height: "20px",
            background: "#222",
            borderRadius: "4px",
            overflow: "hidden"
          }}>
            <div style={{
              width: `${progress}%`,
              height: "100%",
              background: status === "playing" ? "#4CAF50" : "#2196F3",
              transition: "width 0.3s ease"
            }} />
          </div>
          <div style={{ marginTop: "5px", fontSize: "14px", color: "#666" }}>
            {progress.toFixed(1)}%
          </div>
        </div>
      )}

      {/* STATUS MESSAGE */}
      <div style={{ fontSize: "14px", color: "#666" }}>
        {status === "idle" && "Enter a YouTube URL to start"}
        {status === "downloading" && "⏳ Downloading..."}
        {status === "playing" && "▶ Playing in external player"}
        {status === "complete" && "✅ Complete"}
        {status === "error" && (
          <span style={{ color: "#f44336" }}>❌ Error: {errorMessage}</span>
        )}
      </div>

    </div>
  );
}
```

